	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/public/v1/redeem/confirm", wrapper.ConfirmRedeem)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/public/v1/redeem/state", wrapper.GetRedeemState)
